let state,me=null,usage={analyses:0,limit:0},revs={},synced=new Map(),drafts={},pageCache={},saveStatus='ok',retryTimer,installPrompt=null,oldVault=null,authView='login',recoveryShown=null,inviteRequired=false,route='home',profile=null,selected='demo',tab='summary',questionIndex=0,practiceResult=null,ai=false,parent=false,ephemeral=false,saveChain=Promise.resolve(),adminData=null,lastInvite=null,adminRecovery=null,inviteFromLink='';
const $=s=>document.querySelector(s),root=$('#app');
const btn=(text,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
