let archiveSubject='',archiveYear='',archivePeriod='';
const archiveMeta=()=>({subject:$('#subject')?.value||activeProfile().subjects?.[0]||'Wiskunde',schoolYear:$('#school-year-archive')?.value||'2026–2027',period:$('#period-archive')?.value||'Periode 1',chapter:$('#chapter-archive')?.value||'',method:$('#method-archive')?.value||''});
const activeProfile=()=>state.profiles.find(p=>p.id===profile)||state.profiles[0];
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',6000);}
const saveLabel=()=>({ok:'✓ Alles opgeslagen in je account',busy:'Opslaan…',error:'⚠ Nog niet opgeslagen · we proberen het opnieuw'})[saveStatus];
// The sidebar shows the status on large screens; the badge appears on every screen size when saving fails.
function setSave(s){saveStatus=s;const el=$('#save-status');if(el)el.textContent=saveLabel();const badge=$('#save-badge');badge.textContent=s==='error'?saveLabel():'';badge.hidden=s!=='error';}
const markSynced=key=>synced.set(key,records(state,drafts,profile).get(key));
// Sends every changed record in order; a conflict (edited on another device) reloads the newest version instead of overwriting it.
function save(){
 if(ephemeral||!state)return Promise.resolve();setSave('busy');clearTimeout(retryTimer);
 saveChain=saveChain.catch(()=>{}).then(async()=>{
  const current=records(state,drafts,profile),{put,del}=diff(synced,current);
  for(const key of put){const [kind,id]=splitKey(key),data=JSON.parse(current.get(key));
   if(kind==='profile')await call('PUT','/api/profiles/'+id,data);else revs[key]=(await call('PUT',`/api/items/${kind}/${id}`,{data,rev:revs[key]})).rev;
   synced.set(key,current.get(key));}
  for(const key of del){const [kind,id]=splitKey(key);await call('DELETE',`/api/items/${kind}/${id}`);synced.delete(key);delete revs[key];}
  setSave('ok');
 }).catch(async e=>{
  setSave('error');
  if(e.status===409){toast(e.message);await loadState();render();return;}
  if(e.status===401){sessionEnded();return;}
  if(e.status===0)retryTimer=setTimeout(()=>save().catch(()=>{}),15000);
  throw e;
 });
 return saveChain;
}
async function loadState(){
 const s=await call('GET','/api/state');me=s.me;usage=s.usage;revs=s.revs;drafts=s.drafts||{};ephemeral=false;parent=me.role==='parent';
 profile=s.profiles.some(p=>p.id===profile)?profile:me.role==='child'?me.id:s.profiles[0].id;
 state={version:1,profiles:s.profiles,modules:s.modules,documents:s.documents,attempts:s.attempts,draft:drafts[profile]||null};
 if(!state.modules.some(m=>m.id===selected&&!m.deletedAt))selected=state.modules.find(m=>!m.deletedAt)?.id;
 synced=records(state,drafts,profile);setSave('ok');
}
function sessionEnded(){state=null;me=null;authView='login';authScreen();toast('Je bent uitgelogd. Log opnieuw in; je laatste wijziging is mogelijk niet bewaard.');}
const needAccount=()=>{if(ephemeral)throw Error('Maak eerst een gratis account. In de voorbeeldmodus wordt niets bewaard.');};
async function addDocument(d){
 Object.assign(d,archiveMeta());if(ephemeral){state.documents.push(d);return;}
 const {pages,data,...meta}=d,r=await call('POST','/api/documents',{meta,pages,data});
 state.documents.push(r.document);revs['document:'+r.document.id]=r.rev;pageCache[r.document.id]=pages.map(p=>({...p,id:r.document.id}));markSynced('document:'+r.document.id);
}
async function pagesOf(d){return d.pages||pageCache[d.id]||(pageCache[d.id]=(await call('GET',`/api/documents/${d.id}/pages`)).pages);}
const pageCount=d=>d.pageCount??d.pages?.length??0;
const schoolSelects=(prefix,p={})=>`<div><label for="${prefix}-type">Schooltype</label><select id="${prefix}-type">${SCHOOL_TYPES.map(t=>`<option ${(p.schoolType||'havo/vwo')===t?'selected':''}>${t}</option>`).join('')}</select></div><div><label for="${prefix}-year">Leerjaar</label><select id="${prefix}-year">${[1,2,3,4,5,6].map(y=>`<option ${(p.year||1)===y?'selected':''}>${y}</option>`).join('')}</select></div>`;
const download=(blob,name)=>{const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);};
const intro=`<section class="lock-intro"><div class="brand"><span class="brandmark">↗</span>leerstap</div><div class="eyebrow" style="color:#c1d1bc">KLEINE STAPPEN. GROOT VERTROUWEN.</div><h1>Vandaag begrijpen.<br>Morgen zelf kunnen.</h1><p>Upload je eigen leerstof en oefen gericht naar je toets. Fouten komen terug tot je ze snapt. Voor leerlingen én hun ouders.</p></section>`;
const authLinks=`<small class="auth-links">Geen advertenties · Geen tracking · <a href="/voorbeeld-opgaven.pdf" target="_blank" rel="noopener">Voorbeeldproefwerk (PDF)</a> · <a href="/privacy.html">Privacy</a> · <a href="/voorwaarden.html">Voorwaarden</a></small>`;
function authScreen(){
 const tabs=[['login','Inloggen'],['signup','Account maken']],password=(id,label,auto,min)=>`<div><label for="${id}">${label}</label><input id="${id}" type="password" autocomplete="${auto}" ${min?`minlength="${min}"`:''} required></div>`;
 const forms={
  login:`<form id="login-form" class="stack"><h2>Welkom terug</h2><div><label for="login">E-mailadres (ouder) of gebruikersnaam (kind)</label><input id="login" autocomplete="username" autocapitalize="none" spellcheck="false" required></div>${password('password','Wachtwoord','current-password')}<button>Inloggen →</button><p id="auth-error" role="alert" class="danger"></p><small>Wachtwoord vergeten? Ouders gebruiken hun herstelcode: ${btn('wachtwoord herstellen','auth-view','link','data-view="recover" type="button"')}. Kinderen vragen hun ouder om een nieuw wachtwoord.</small></form>`,
  signup:`<form id="signup-form" class="stack"><h2>Maak jullie gezinsaccount</h2><p class="muted" style="margin:0">Voor ouders en verzorgers. Daarna geef je ieder kind een eigen login. Gratis tijdens de proefperiode.</p><div><label for="email">Jouw e-mailadres</label><input id="email" type="email" autocomplete="email" required></div>${password('new-password','Wachtwoord (minimaal 10 tekens)','new-password',10)}${password('confirm','Herhaal het wachtwoord','new-password',10)}<div><label for="child-name">Naam of bijnaam van je kind</label><input id="child-name" maxlength="40" placeholder="Bijvoorbeeld: Sam" required></div><div class="grid">${schoolSelects('signup',{year:2})}</div>${inviteRequired?`<div><label for="invite">Uitnodigingscode</label><input id="invite" autocomplete="off" autocapitalize="characters" value="${esc(inviteFromLink)}" required></div>`:''}<label class="checkline"><input type="checkbox" id="accept" required><span>Ik ben ouder of verzorger en ga akkoord met de <a href="/voorwaarden.html" target="_blank">voorwaarden</a> en het <a href="/privacy.html" target="_blank">privacybeleid</a>.</span></label><button>Account maken →</button><p id="auth-error" role="alert" class="danger"></p></form>`,
  recover:`<form id="recover-form" class="stack"><h2>Wachtwoord herstellen</h2><p class="muted" style="margin:0">Gebruik de herstelcode die je kreeg bij het aanmaken van je account.</p><div><label for="recover-email">E-mailadres</label><input id="recover-email" type="email" autocomplete="email" required></div><div><label for="recover-code">Herstelcode</label><input id="recover-code" autocomplete="off" autocapitalize="characters" placeholder="XXXXX-XXXXX-XXXXX-XXXXX" required></div>${password('new-password','Nieuw wachtwoord (minimaal 10 tekens)','new-password',10)}${password('confirm','Herhaal het wachtwoord','new-password',10)}<button>Nieuw wachtwoord instellen →</button><p id="auth-error" role="alert" class="danger"></p></form>`};
 const recovery=`<div class="stack"><span class="eyebrow">BELANGRIJK</span><h2>Bewaar je herstelcode</h2><p class="muted" style="margin:0">Hiermee stel je een nieuw wachtwoord in als je het vergeet. We tonen de code maar één keer en kunnen hem niet opnieuw opvragen.</p><div class="recovery-code" id="recovery-code">${esc(recoveryShown)}</div><div class="row">${btn('Kopiëren','copy-recovery','secondary small')}${btn('Downloaden','download-recovery','secondary small')}</div><label class="checkline"><input type="checkbox" id="recovery-saved"><span>Ik heb de herstelcode veilig bewaard.</span></label>${btn('Verder naar Leerstap →','recovery-done')}</div>`;
 root.innerHTML=`<div class="lockscreen">${intro}<section class="lock-form">${recoveryShown?recovery:`<div class="tabs">${tabs.map(([v,t])=>btn(t,'auth-view',authView===v?'':'secondary',`data-view="${v}"`)).join('')}</div>${forms[authView]}<div class="auth-alt">${btn('Bekijk eerst de voorbeeldles, zonder account','demo','ghost')}</div>${authLinks}`}</section></div>`;
}
async function authSubmit(form){
 const v=id=>$('#'+id)?.value??'',err=$('#auth-error');err.textContent='';
 if(form==='login-form'){await call('POST','/api/login',{login:v('login').trim(),password:v('password')});await loadState();route='home';render();return;}
 if(v('new-password')!==v('confirm'))throw Error('De wachtwoorden zijn niet gelijk.');
 if(form==='signup-form'){const r=await call('POST','/api/signup',{email:v('email').trim(),password:v('new-password'),childName:v('child-name').trim(),schoolType:v('signup-type'),year:Number(v('signup-year')),invite:v('invite'),accept:$('#accept').checked});recoveryShown=r.recoveryCode;authScreen();return;}
 if(form==='recover-form'){const r=await call('POST','/api/recover',{email:v('recover-email').trim(),code:v('recover-code'),password:v('new-password')});recoveryShown=r.recoveryCode;authScreen();toast('Je wachtwoord is gewijzigd. Je hebt een nieuwe herstelcode.');}
}
const SUBJECTS=['Wiskunde','Nederlands','Engels','Biologie','Geschiedenis','Aardrijkskunde','Natuurkunde','Scheikunde','NaSk','Duits','Frans','Economie','Maatschappijleer','Latijn','Grieks','Techniek','Kunst & cultuur'];
function curriculum(){const p=activeProfile(),subjects=p.subjects||['Wiskunde'],types=['vmbo-basis','vmbo-kader','vmbo-gl','vmbo-tl','havo','vwo','gymnasium','havo/vwo'];return `<div class="card"><span class="eyebrow">MIJN SCHOOL & VAKKEN</span><h2 style="margin-top:12px">Een leerplek voor ${esc(p.name)}</h2><div class="grid"><div><label for="school-type">Schooltype</label><select id="school-type">${types.map(t=>`<option ${(p.schoolType||'havo/vwo')===t?'selected':''}>${t}</option>`).join('')}</select></div><div><label for="school-year">Leerjaar</label><select id="school-year">${[1,2,3,4,5,6].map(y=>`<option ${(p.year||2)===y?'selected':''}>${y}</option>`).join('')}</select></div></div><p class="muted">Vink de vakken aan die je volgt. De leerstof zelf voeg je per hoofdstuk toe.</p><div class="subject-grid">${[...new Set([...SUBJECTS,...subjects])].map(s=>`<label class="subject-choice"><input type="checkbox" name="chosen-subject" value="${esc(s)}" ${subjects.includes(s)?'checked':''}>${esc(s)}</label>`).join('')}</div><div class="row" style="margin-top:20px"><div style="flex:1"><label for="custom-subject">Eigen vak (optioneel)</label><input id="custom-subject" maxlength="50" placeholder="Bijvoorbeeld: Spaans"></div>${btn('School & vakken bewaren','save-subjects')}</div><small style="display:block;margin-top:14px">Deze selectie organiseert je leerplek. AI-analyse gebruikt je niveau en de toegevoegde bronnen; vakinhoud wordt niet automatisch als correct beschouwd.</small></div>`;}
const icons={home:'⌂',library:'▤',practice:'✎',test:'✓',progress:'▥',settings:'⚙',admin:'✉'};
function render(){if(!state)return authScreen();let nav=[['home','Mijn leerplek'],['library','Mijn leerstof'],['practice','Oefenen'],['test','Proefwerk'],['progress','Voortgang'],['settings','Gezin & instellingen'],...me?.admin&&!ephemeral?[['admin','Beheer']]:[]];root.innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><span class="brandmark">↗</span><div>leerstap<small>SAMEN VOORUIT</small></div></div><div class="eyebrow">JOUW LEERPLEK</div><nav class="nav">${nav.map(([r,t])=>btn(`<span>${icons[r]}</span>${t}`,'nav',route===r?'active':'',`data-route="${r}"`)).join('')}</nav><div class="sidebar-foot"><b><span class="status-dot"></span>Op jouw tempo</b><br>Een fout laat zien wat je nog kunt leren.<br><br><small id="save-status">${ephemeral?'Voorbeeldmodus · er wordt niets bewaard':saveLabel()}</small>${installPrompt?`<div style="margin-top:12px">${btn('Installeer als app','install','ghost small')}</div>`:''}</div></aside><main class="main"><header class="topbar"><span class="muted">Mijn leerplek <span style="margin:0 9px">/</span> ${nav.find(n=>n[0]===route)?.[1]||'Leerstof'}</span><div class="profile"><span class="avatar">${esc(activeProfile().name.charAt(0))}</span>${parent?`<select id="profile" aria-label="Leerling">${state.profiles.map(p=>`<option value="${esc(p.id)}" ${p.id===profile?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`:`<b>${esc(activeProfile().name)}</b>`}${btn(ephemeral?'Account maken':'Uitloggen','lock','ghost small')}</div></header>${ephemeral?`<div class="notice">Voorbeeldmodus: er wordt niets bewaard. ${btn('Maak een gratis account','lock','small')} om je voortgang op te slaan en je eigen leerstof toe te voegen.</div>`:''}${!ephemeral&&parent&&state.modules.some(m=>!m.approved&&!m.deletedAt)&&route!=='detail'?`<div class="notice">Er staat nieuwe leerstof klaar voor jouw controle. ${btn('Bekijken','module','ghost small',`data-id="${esc(state.modules.find(m=>!m.approved&&!m.deletedAt).id)}"`)}</div>`:''}<div id="content">${({home,library,practice,test:testPage,progress,settings,detail,admin:adminView})[route]?.()||home()}</div><footer><span>Leerstap · versie ${VERSION} · ${esc(activeProfile().level)}</span><span>${ai?'AI gekoppeld · oudercontrole blijft nodig':'AI nog niet gekoppeld · voorbeeldles werkt'} · ${ephemeral?'voorbeeldmodus':parent?'ouder':'leerling'} · <a href="/privacy.html">privacy</a></span></footer></main></div>`;}
function home(){const attempts=state.attempts.filter(a=>a.profile===profile),answered=attempts.reduce((s,a)=>s+a.questions.length,0),due=dueCount(),completed=attempts.filter(a=>!totals(a.results,a.questions).pending);return `<div class="hero"><div><span class="eyebrow">JOUW VOLGENDE STAP</span><h1>Fijn dat je er bent,<br>${esc(activeProfile().name)}.</h1><p>Een beetje oefenen maakt een groot verschil.<br>Waar wil jij vandaag beter in worden?</p>${btn('Verder met oefenen <span style="margin-left:15px">→</span>','go-practice')}</div><div class="hero-art" aria-hidden="true"><div class="orbit"><div class="mathcard">√81 <span style="color:#8da46c;font-size:25px">= 9</span></div></div><div class="spark">✦</div><div class="floatlabel">✓ Ik begrijp het!</div></div></div><div class="stats"><div class="stat"><span class="stat-icon">✎</span><div><b>${answered}</b><small>vragen geoefend</small></div></div><div class="stat"><span class="stat-icon">↻</span><div><b>${due}</b><small>klaar voor herhaling</small></div></div><div class="stat"><span class="stat-icon">✓</span><div><b>${completed.length}</b><small>sessies afgerond</small></div></div></div><div class="section-head"><h2>Jouw leerstof</h2>${btn('+ Leerstof toevoegen','go-library','ghost small')}</div><div class="grid main-grid"><div>${state.modules.filter(m=>!m.deletedAt).slice(0,3).map(moduleCard).join('')}</div><div class="card"><span class="eyebrow">ZO WERKT HET</span><h3 style="margin-top:12px">Van lezen naar weten</h3>${[['Voeg je leerstof toe','Upload een hoofdstuk, foto of je aantekeningen.'],['Begrijp de kern','Bekijk de samenvatting en leerdoelen.'],['Oefen op jouw niveau','Krijg hints, uitleg en tijd om te groeien.']].map(([t,d],i)=>`<div class="step"><span class="step-number">${i+1}</span><div><b style="font-size:13px">${t}</b><p>${d}</p></div></div>`).join('')}<div class="notice" style="margin-bottom:0">Liever op papier? Bij elk proefwerk kun je de opgaven en antwoorden apart downloaden.</div></div></div>`;}
function moduleCard(m){const attempts=state.attempts.filter(a=>a.profile===profile&&a.module===m.id),done=[...new Map(attempts.flatMap(a=>a.questions.map((q,i)=>[q.id,!q.support&&!a.results[i].pending&&a.results[i].points===q.points]))).values()].filter(Boolean).length,pct=Math.round(done/m.questions.length*100);return `<article class="card"><div class="row between"><div class="row"><span class="module-icon">${m.subject==='Wiskunde'?'√':'Aa'}</span><div><span class="pill">${esc(m.subject)}</span> <small>${esc(m.level)}</small></div></div><span class="pill ${m.approved?'':'orange'}">${m.demo?'Voorbeeldles':m.approved?'Vrijgegeven':'Oudercontrole'}</span></div><h3 class="module-title">${esc(m.title)}</h3><p class="muted" style="font-size:12px;margin:0 0 8px">${esc([m.schoolYear,m.period,m.chapter,m.method].filter(Boolean).join(' · ')||'Voorbeeldarchief')}</p><small>${m.chapters.length} hoofdstuk(ken) · ${m.questions.length} vragen · basis tot inzicht</small><div class="progress"><i style="width:${pct}%"></i></div><div class="row between"><small>${done} van ${m.questions.length} laatste keer zelfstandig goed</small>${btn('Bekijk leerstof →','module','ghost small',`data-id="${esc(m.id)}"`)}</div></article>`;}

function archiveView(){const modules=state.modules.filter(m=>!m.deletedAt),filtered=modules.filter(m=>(!archiveSubject||m.subject===archiveSubject)&&(!archiveYear||m.schoolYear===archiveYear)&&(!archivePeriod||m.period===archivePeriod));const select=(id,label,value,values)=>`<div><label for="${id}">${label}</label><select id="${id}"><option value="">Alles</option>${[...new Set(values.filter(Boolean))].sort().map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`;const trash=[...state.modules.filter(m=>m.deletedAt).map(m=>({...m,kind:'module',name:m.title})),...state.documents.filter(d=>d.deletedAt).map(d=>({...d,kind:'document'}))];return `<div class="section-head"><div><h2>Mijn leerarchief</h2><p class="muted" style="font-size:13px">Bewaar je samenvattingen voor de volgende toets. Filter op vak, schooljaar en periode.</p></div></div><div class="card"><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(140px,1fr))">${select('archive-subject','Vak',archiveSubject,modules.map(m=>m.subject))}${select('archive-year','Schooljaar',archiveYear,modules.map(m=>m.schoolYear))}${select('archive-period','Periode',archivePeriod,modules.map(m=>m.period))}</div></div><div class="grid" style="margin-top:18px">${filtered.length?filtered.map(moduleCard).join(''):'<div class="card empty">Geen leerstof voor deze selectie. Kies een ander filter.</div>'}</div><details class="card" style="margin-top:25px"><summary>Prullenbak · ${trash.length} item(s)</summary><p class="muted">Herstellen behoudt de oorspronkelijke indeling. Er wordt niets automatisch gewist. Definitief verwijderen vraagt oudermodus.</p>${trash.map(x=>`<div class="list-item row between"><div><b>${esc(x.name)}</b><br><small>${x.kind==='document'?'Bronbestand':'Leermodule'} · ${new Date(x.deletedAt).toLocaleDateString('nl-NL')}</small></div><div class="row">${btn('Herstellen','restore-item','secondary small',`data-kind="${x.kind}" data-id="${x.id}"`)}${btn('Definitief verwijderen','destroy-item','ghost small danger',`data-kind="${x.kind}" data-id="${x.id}"`)}</div></div>`).join('')}</details>`;}
function moduleOrganizer(m){const field=(id,label,value)=>`<div><label for="${id}">${label}</label><input id="${id}" value="${esc(value||'')}" maxlength="150"></div>`;return `<details class="card"><summary>Naam & opslaglocatie wijzigen</summary><p class="muted">Indeling: vak → schooljaar → periode → hoofdstuk. De inhoud en eerdere resultaten veranderen niet.</p><div class="grid">${field('edit-title','Titel',m.title)}${field('edit-subject','Vak',m.subject)}${field('edit-year','Schooljaar',m.schoolYear||'2026–2027')}${field('edit-period','Periode',m.period||'Periode 1')}${field('edit-chapter','Hoofdstuk',m.chapter)}${field('edit-method','Lesmethode',m.method)}</div><div style="margin-top:18px">${btn('Indeling bewaren','save-module-meta')}</div></details>`;}

function library(){return `<div class="section-head"><div><span class="eyebrow">JOUW BRONNEN, JOUW LEERSTOF</span><h1>Alles op één plek.</h1></div></div><div class="grid"><section class="card"><h2>Leerstof toevoegen</h2><div class="upload-zone"><div style="font-size:30px;margin-bottom:10px">↥</div><b>Een hoofdstuk begint hier</b><p>PDF, DOCX, tekst of foto’s · meerdere bestanden<br>Max. 10 MB per bestand, 30 pagina’s per analyse</p><input type="file" id="files" multiple accept=".pdf,.docx,.txt,.md,.png,.jpg,.jpeg,.webp" aria-label="Bestanden uploaden"></div><details><summary>Of plak je tekst</summary><label for="pasted-name">Titel</label><input id="pasted-name" placeholder="Bijvoorbeeld: biologie hoofdstuk 3"><label for="pasted" style="margin-top:10px">Leerstof</label><textarea id="pasted" placeholder="Plak hier je eigen aantekeningen..."></textarea>${btn('Tekst bewaren','paste','secondary')}</details><div class="notice">Upload alleen materiaal dat jullie mogen gebruiken. Namen of andere privégegevens zijn niet nodig.</div></section><section class="card"><h2>Klaar voor analyse</h2>${state.documents.some(d=>!d.deletedAt)?state.documents.filter(d=>!d.deletedAt).map(d=>`<div class="list-item"><label class="checkline"><input type="checkbox" name="document" value="${d.id}" checked><span>${esc(d.name)}<br><small>${pageCount(d)} pagina / tekstdeel · ${esc(d.subject||'Nog indelen')} · ${esc(d.period||'')}</small></span></label>${d.warnings.map(w=>`<small class="danger">${esc(w)}</small><br>`).join('')}${btn('Bron bekijken','source','ghost small',`data-id="${d.id}" data-page="1"`)} ${btn('Naar prullenbak','trash-document','ghost small',`data-id="${d.id}"`)}</div>`).join(''):'<p class="muted">Je geüploade bronnen verschijnen hier. Ze blijven ook bewaard als analyse niet lukt.</p>'}<div class="grid" style="margin:18px 0"><div><label for="subject">Vak</label><input id="subject" value="${esc(activeProfile().subjects?.[0]||'Wiskunde')}" list="subjects"><datalist id="subjects">${[...new Set([...(activeProfile().subjects||[]),...SUBJECTS])].map(s=>`<option>${esc(s)}</option>`).join('')}</datalist></div><div><label for="level">Niveau</label><input id="level" value="${esc(activeProfile().level)}"></div></div><div class="grid" style="margin-bottom:18px"><div><label for="school-year-archive">Schooljaar</label><input id="school-year-archive" value="2026–2027" maxlength="30"></div><div><label for="period-archive">Periode</label><input id="period-archive" value="Periode 1" list="periods" maxlength="50"><datalist id="periods"><option>Periode 1</option><option>Periode 2</option><option>Periode 3</option><option>Periode 4</option><option>Examenvoorbereiding</option></datalist></div><div><label for="chapter-archive">Hoofdstuk</label><input id="chapter-archive" placeholder="Bijv. H3 · Wortels" maxlength="100"></div><div><label for="method-archive">Lesmethode (optioneel)</label><input id="method-archive" placeholder="Bijv. Getal & Ruimte" maxlength="100"></div></div>${ephemeral?'<div class="notice">In de voorbeeldmodus kun je bestanden inlezen en bekijken, maar niet laten analyseren. Maak een gratis account om je eigen leerstof om te zetten in samenvattingen en oefenvragen.</div>':me.aiConsent?'<p class="muted" style="font-size:13px">Een ouder heeft toestemming gegeven om gekozen leerstof voor analyse naar OpenAI te sturen. Namen, antwoorden en voortgang gaan niet mee.</p>':parent?'<label class="checkline"><input type="checkbox" id="consent"><span>Ik ben de ouder en geef toestemming om gekozen leerstof voor analyse naar OpenAI te sturen. Namen, antwoorden en voortgang gaan niet mee. Intrekken kan bij Gezin & instellingen.</span></label>':'<div class="notice">Vraag je ouder om AI-analyse aan te zetten bij Gezin & instellingen.</div>'}${btn(ai?'Maak samenvatting & vragen →':'AI-koppeling controleren','analyse')}<small style="display:block;margin-top:12px">${ai?`Resultaten komen eerst in oudercontrole.${ephemeral?'':` · ${usage.analyses} van ${usage.limit} analyses gebruikt deze maand`}`:'Nog nodig: een API-sleutel op de server. Er wordt geen nep-analyse gemaakt.'}</small></section></div>${archiveView()}`;}
function citation(c){return `<div class="source">Bron · pagina / tekstdeel ${c.page} ${btn('Open bron ↗','source','ghost small',`data-id="${esc(c.source)}" data-page="${c.page}"`)}<br>“${esc(c.quote)}”</div>`;}
function detail(){const m=activeModule();return `<span class="eyebrow">${esc(m.subject)} · ${esc(m.level)}</span><h1>${esc(m.title)}</h1>${moduleOrganizer(m)}${m.demo?'<div class="notice">Nieuwe voorbeeldmodule, handmatig opgesteld. Dit is geen analyse van de afbeeldingen uit de eerdere chat.</div>':''}${!m.approved?(parent?`<div class="notice">Concept: controleer alle broncitaten, uitleg, antwoorden en punten voordat je dit vrijgeeft. Een bestaand citaat bewijst nog niet dat de uitleg klopt. ${btn('Vrijgeven na controle','approve','small')}</div>`:'<div class="notice">Deze leerstof is nieuw. Je ouder controleert hem en geeft hem daarna vrij om mee te oefenen. Lezen kan alvast.</div>'):''}${(m.warnings||[]).map(w=>`<div class="notice error">${esc(w)}</div>`).join('')}<div class="tabs">${btn('Samenvatting & begrippen','tab',tab==='summary'?'':'secondary','data-tab="summary"')}${btn('Vragen & puntenmodel','tab',tab==='questions'?'':'secondary','data-tab="questions"')}${m.approved?btn('Ga oefenen →','go-practice','ghost'):''}</div>${tab==='summary'?m.chapters.map(c=>`<section class="card"><h2>${esc(c.title)}</h2><p>${esc(c.summary)}</p><h3>Dit ga je leren</h3><ul>${c.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><h3>Begrippen</h3>${c.terms.map(t=>`<p><b>${esc(t.term)}</b> — ${esc(t.definition)}</p>`).join('')}${citation(c.cite)}</section>`).join(''):m.questions.map((q,i)=>`<section class="card"><div class="row between"><span class="pill">Niveau ${q.level} · ${esc(q.goal)}</span><small>${q.points} punten</small></div><h3 style="margin-top:17px">${i+1}. ${esc(q.prompt)}</h3><details><summary>Antwoord, uitwerking & punten</summary><p><b>${esc(q.answer)}</b><br>${esc(q.explanation)}</p><p>${esc(q.rubric)}</p></details>${citation(q.cite)}</section>`).join('')}<div class="notice">Niet meer nodig? ${btn('Naar prullenbak','remove-module','ghost small')} Bronnen en eerdere toetsresultaten blijven bewaard. Herstellen kan via Mijn leerstof.</div>`;}
function moduleSelect(){return `<label for="module-select">Kies je leerstof</label><select id="module-select">${state.modules.filter(m=>m.approved&&!m.deletedAt).map(m=>`<option value="${esc(m.id)}" ${m.id===selected?'selected':''}>${esc(m.title)} · ${esc(m.subject)}</option>`).join('')}</select>`;}
function setup(mode){return `<span class="eyebrow">${mode==='test'?'LAAT ZIEN WAT JE KUNT':'ELKE OEFENING IS EEN STAP'}</span><h1>${mode==='test'?'Klaar voor je proefwerk?':'Oefen met vertrouwen.'}</h1><div class="grid main-grid"><div class="card stack">${moduleSelect()}<div class="grid"><div><label for="difficulty">Moeilijkheid</label><select id="difficulty"><option value="adaptief">Adaptief · fouten eerst</option><option value="1">1 · Basis</option><option value="2">2 · Toepassen</option><option value="3">3 · Inzicht</option></select></div><div><label for="count">Aantal vragen</label><select id="count"><option>5</option><option>9</option><option>15</option></select></div></div><small>Maximaal het aantal beschikbare vragen. Adaptief kiest eerdere fouten, herhaling en daarna nieuwe vragen.</small>${btn(mode==='test'?'Start proefwerk →':'Start oefensessie →','start','',`data-mode="${mode}"`)}${mode==='test'?`<div class="row">${btn('↓ PDF opgaven','pdf','ghost','data-answers="false"')}${btn('↓ PDF antwoorden','pdf','ghost','data-answers="true"')}</div>`:''}</div><div class="card"><h3>${mode==='test'?'Rustig werken, eerlijk nakijken':'Leren mag met hulp'}</h3><p class="muted">${mode==='test'?'Je krijgt pas na inleveren je antwoorden en uitleg. Tussenstappen tellen mee via ouderreview.':'Je krijgt een korte hint als je vastloopt. Na elke vraag lees je hoe je tot het antwoord komt.'}</p><div class="notice">${mode==='test'?'Dit is een oefentoets voor thuis. Leerlingen kunnen de antwoorden in de leerstof bekijken; dit is geen beveiligde schoolexamenomgeving.':'Typ bijvoorbeeld √81, sqrt(81), 2*sqrt(3) of 1/2. Gebruik een komma of punt voor decimalen.'}</div></div></div>`;}
function practice(){return state.draft?.profile===profile&&state.draft.mode==='practice'?sessionPage():setup('practice');}
function testPage(){return state.draft?.profile===profile&&state.draft.mode==='test'?sessionPage():setup('test');}
function sessionPage(){const d=state.draft;questionIndex=Math.min(d.position??questionIndex,d.questions.length-1);const q=d.questions[questionIndex],a=d.answers[questionIndex]||{answer:'',steps:''},r=practiceResult||d.results?.[questionIndex];return `<div class="row between"><span class="eyebrow">${d.mode==='test'?'PROEFWERK':'OEFENEN'} · ${esc(d.title)}</span><small>Vraag ${questionIndex+1} van ${d.questions.length}</small></div><div class="progress"><i style="width:${(questionIndex+1)/d.questions.length*100}%"></i></div><div class="card" style="margin-top:24px"><div class="row between"><span class="pill">${esc(q.goal)} · niveau ${q.level}</span><small>${q.points} punten</small></div>${d.mode==='practice'&&q.repeat?`<div class="notice"><b>${q.support?'Eerst even opfrissen':'Nu zelfstandig terughalen'}</b><p>${q.support?esc(q.explanation):'Deze vraag kwam eerder lastig uit. Probeer hem opnieuw zonder uitleg.'}</p><small>Na een fout oefenen we tot twee zelfstandige antwoorden achter elkaar goed zijn.</small></div>`:''}<h2 class="question">${questionIndex+1}. ${esc(q.prompt)}</h2><label for="answer">Jouw antwoord</label><input id="answer" class="answerbox" value="${esc(a.answer)}" autocomplete="off" placeholder="Typ je antwoord..." ${r?'disabled':''}><div class="keypad">${['√','²','(',')','×','÷'].map(k=>btn(k,'symbol','',`data-symbol="${k}" ${r?'disabled':''}`)).join('')}</div><label for="steps">Jouw tussenstappen <small>— één stap per regel</small></label><textarea id="steps" placeholder="Hoe heb je het aangepakt?" ${r?'disabled':''}>${esc(a.steps)}</textarea>${d.mode==='practice'?`<details><summary>Geef me een kleine hint</summary><p>${esc(q.hint)}</p></details>`:''}${r?`<div class="feedback ${r.pending?'pending':''}"><b>${r.pending?'Ouderreview nodig':r.points===q.points?'Goed gedaan!':'Hier kun je van leren'}</b><p>${esc(r.feedback)}</p><small>${r.points} / ${q.points} punten ${r.pending?'· voorlopig':''} · betrouwbaarheid: ${esc(r.confidence)}</small></div>`:''}<div class="row between" style="margin-top:24px">${btn('← Vorige','previous','ghost',questionIndex===0||d.mode==='practice'?'disabled':'')}<div class="row">${d.mode==='practice'&&!r?btn('Controleer antwoord','check'):questionIndex<d.questions.length-1?btn('Volgende vraag →','next'):btn('Afronden & nakijken','finish')}</div></div></div>${d.mode==='practice'?btn('Stoppen en beantwoorde vragen bewaren','finish-early','ghost'):''}<p class="muted" style="font-size:12px">${ephemeral?'Voorbeeldmodus: antwoorden worden niet bewaard.':'Antwoorden worden automatisch bewaard. Je kunt later verdergaan, ook op een ander apparaat.'}</p>`;}
function dueCount(){const map=new Map();for(let a of state.attempts.filter(a=>a.profile===profile))for(let [id,r] of Object.entries(a.review||{}))map.set(id,r);return [...map.values()].filter(r=>r.due<=Date.now()).length;}
function progress(){const attempts=state.attempts.filter(a=>a.profile===profile).slice().reverse();return `<span class="eyebrow">KIJK EENS HOEVER JE BENT</span><h1>Jouw groei in beeld.</h1>${attempts.length?'':`<div class="card empty">Je hebt nog geen sessie afgerond. Begin met een paar oefenvragen; je voortgang verschijnt hier.</div>`}${attempts.map(a=>{const t=totals(a.results,a.questions),errors=a.questions.filter((q,i)=>a.results[i].points<q.points);return `<section class="card"><div class="row between"><div><span class="pill">${a.mode==='test'?'Proefwerk':'Oefensessie'}</span><h2 style="margin-top:14px">${esc(a.title)}</h2><small>${new Date(a.created).toLocaleString('nl-NL')} · ${t.points} / ${t.max} punten</small></div><div style="text-align:right"><div class="score">${String(t.grade).replace('.',',')}</div><small>${t.pending?'Voorlopig · review nodig':a.mode==='practice'?'Oefenscore inclusief herhalingen':'Oefencijfer proefwerk'}</small></div></div>${t.pending?`<div class="notice">Er staan antwoorden open voor ouderreview. Het cijfer gebruikt voorlopig 0 punten voor die antwoorden. ${parent?'Beoordeel ze hieronder bij „Antwoorden, feedback & deelpunten”.':'Je ouder beoordeelt ze.'}</div>`:''}<p class="muted">${errors.length?'Foutfocus: '+esc([...new Set(errors.map(q=>q.goal))].join(', ')):'Alle antwoorden goed. Mooi werk! Herhaal later om het vast te houden.'}</p><details><summary>Antwoorden, feedback & deelpunten</summary>${a.questions.map((q,i)=>{const r=a.results[i];return `<div class="list-item"><b>${i+1}. ${esc(q.prompt)}</b><p>Jouw antwoord: ${esc(a.answers[i]?.answer||'—')}<br><span class="muted">${esc(a.answers[i]?.steps||'Geen tussenstappen')}</span></p><p>${esc(r.feedback)}</p><small>${r.points}/${q.points} punten · ${r.pending?'review nodig':esc(r.confidence)} · ${esc(r.category)}</small><details><summary>Puntenmodel</summary><p>${esc(q.rubric)}</p><p>Antwoord: ${esc(q.answer)}</p></details>${parent?`<div class="row"><label style="margin:0">Punten <input style="width:85px" id="score-${a.id}-${i}" type="number" min="0" max="${q.points}" step="0.5" value="${r.points}"></label><label style="flex:1">Toelichting<input id="note-${a.id}-${i}" placeholder="Waarom krijgt dit antwoord deze punten?"></label>${btn('Review opslaan','review','small',`data-id="${a.id}" data-index="${i}"`)}</div>`:''}${r.reviewNote?`<p>Ouder: ${esc(r.reviewNote)}</p>`:''}</div>`;}).join('')}</details></section>`;}).join('')}<div class="notice">Cijfer = 1 + 9 × punten / totaal, afgerond op één decimaal. Herhaling: na 1 dag; bij goed antwoord verdubbelt het interval tot maximaal 30 dagen. Geen automatische notificaties.</div>`;}
const suggestLogin=name=>name.toLowerCase().normalize('NFD').replace(/[^a-z0-9]/g,'').slice(0,20)||'leerling';
function childrenCard(){return `<section class="card"><h2>Leerlingen</h2>${state.profiles.map(p=>`<div class="list-item"><div class="row between"><b>${esc(p.name)}</b><small>${esc(p.level)}</small></div><small>${ephemeral?'Voorbeeldprofiel':p.login?`Logt zelf in als <b>${esc(p.login)}</b>`:'Nog geen eigen login · gebruikt jouw account'}</small>${ephemeral?'':`<details><summary>${p.login?'Gebruikersnaam of wachtwoord wijzigen':'Eigen login geven'}</summary><div class="stack"><div><label for="child-login-${p.id}">Gebruikersnaam</label><input id="child-login-${p.id}" value="${esc(p.login||suggestLogin(p.name))}" autocomplete="off" autocapitalize="none" spellcheck="false" maxlength="30"></div><div><label for="child-password-${p.id}">${p.login?'Nieuw wachtwoord':'Wachtwoord'} (minimaal 8 tekens)</label><input id="child-password-${p.id}" autocomplete="off" spellcheck="false" minlength="8"></div>${btn('Login opslaan','child-login','secondary small',`data-id="${p.id}"`)}<small>Je kind logt op elk apparaat in met deze gebruikersnaam en dit wachtwoord en ziet alleen de eigen voortgang. Een nieuw wachtwoord meldt je kind overal af.</small></div></details>${state.profiles.length>1?`<details><summary class="danger">Leerling verwijderen</summary><p class="muted">Dit verwijdert de login, antwoorden en voortgang van ${esc(p.name)} definitief. Gedeelde leerstof blijft bestaan.</p>${btn('Definitief verwijderen','remove-child','ghost small danger',`data-id="${p.id}"`)}</details>`:''}`}</div>`).join('')}<h3 style="margin-top:22px">Kind toevoegen</h3><div class="stack"><div><label for="new-name">Naam of bijnaam</label><input id="new-name" maxlength="40" placeholder="Bijvoorbeeld: Noor"></div><div class="grid">${schoolSelects('new',{year:1})}</div>${btn('Kind toevoegen','add-profile','secondary')}</div></section>`;}
function aiCard(){return `<section class="card"><h2>AI & privacy</h2><span class="pill ${ai?'':'orange'}">${ai?'AI-dienst gekoppeld':'AI-dienst nog niet gekoppeld'}</span> <span class="pill ${me.aiConsent?'':'orange'}">${me.aiConsent?'Toestemming gegeven':'Geen toestemming'}</span><p>Bij een analyse stuurt Leerstap alleen de gekozen bronpagina’s, het vak en het niveau naar OpenAI. Namen, antwoorden en voortgang gaan niet mee. Leerstap vraagt OpenAI de aanvraag niet te bewaren (store: false); hun verwerkersvoorwaarden blijven gelden.</p>${ephemeral?'':`<p class="muted">Deze maand: ${usage.analyses} van ${usage.limit} analyses gebruikt.</p>`}${parent&&!ephemeral?btn(me.aiConsent?'Toestemming intrekken':'Toestemming geven voor AI-analyse',me.aiConsent?'consent-off':'consent-on','secondary'):''}<p class="muted" style="font-size:12px">Met toestemming kunnen ook je kinderen hun leerstof laten analyseren. Wat de AI maakt blijft een concept tot een ouder het vrijgeeft. Meer in het <a href="/privacy.html">privacybeleid</a>.</p></section>`;}
function accountCard(){
 if(ephemeral)return `<section class="card"><h2>Bewaar je voortgang</h2><p>Je bekijkt de voorbeeldles. Met een gratis gezinsaccount bewaar je alles automatisch, geef je ieder kind een eigen login en voeg je je eigen leerstof toe.</p>${btn('Account maken →','lock')}</section>`;
 return `<section class="card"><h2>Mijn account</h2><p>Ingelogd als <b>${esc(me.login)}</b>${parent?` · ${esc(me.familyName)}`:''}.</p><details><summary>Wachtwoord wijzigen</summary><div class="stack"><div><label for="pw-current">Huidig wachtwoord</label><input id="pw-current" type="password" autocomplete="current-password"></div><div><label for="pw-new">Nieuw wachtwoord (minimaal ${parent?10:8} tekens)</label><input id="pw-new" type="password" autocomplete="new-password"></div>${btn('Wachtwoord wijzigen','change-password','secondary small')}</div></details>${btn('Uitloggen','lock','ghost')}${parent?`<details><summary class="danger">Gezinsaccount verwijderen</summary><p>Hiermee verwijder je alle leerlingen, logins, leerstof, bronnen en resultaten van jullie gezin definitief. Download eerst een back-up als je iets wilt bewaren.</p><label for="delete-password">Je wachtwoord</label><input id="delete-password" type="password" autocomplete="current-password"><label for="delete-confirm" style="margin-top:10px">Typ VERWIJDER</label><input id="delete-confirm">${btn('Alles definitief verwijderen','delete','ghost danger')}</details>`:''}</section>`;}
function backupCard(){return `<section class="card"><h2>Back-up & overstappen</h2><p>Alles staat in jullie account en wordt automatisch opgeslagen. Wil je ook zelf een kopie? Download een versleutelde back-up met alle bronnen, leerstof en resultaten.</p><label for="backup-password">Wachtwoord voor de back-up (minimaal 10 tekens)</label><input id="backup-password" type="password" autocomplete="new-password"><div style="margin-top:12px">${btn('↓ Download versleutelde back-up','backup')}</div>${oldVault?`<div class="notice"><b>Gezinskluis van de vorige versie gevonden</b><p>Op dit apparaat staat nog een kluis uit Leerstap 0.1/0.2. Zet hem over naar je account met het oude gezinswachtwoord. De oude kluis blijft ongewijzigd staan.</p><label for="old-vault-password">Oud gezinswachtwoord</label><input id="old-vault-password" type="password" autocomplete="off">${btn('Kluis overzetten','import-old-vault','secondary small')}</div>`:''}<details><summary>Back-up importeren</summary><p>Voor een back-up uit deze of de vorige versie. Leerlingen uit de back-up worden toegevoegd; onderdelen die al bestaan worden overgeslagen.</p><input type="file" id="import-file" accept=".json"><label for="import-password">Wachtwoord van de back-up</label><input type="password" id="import-password">${btn('Controleer & importeer','import','secondary')}</details></section>`;}
function installCard(){return `<section class="card"><h2>Leerstap als app</h2><p>Zet Leerstap op het beginscherm van je telefoon, tablet of computer. Het opent dan als een app en je blijft ingelogd.</p>${installPrompt?btn('App installeren','install'):''}<p class="muted" style="font-size:13px"><b>Android (Chrome):</b> menu ⋮ → <i>App installeren</i> of <i>Toevoegen aan startscherm</i>.<br><b>iPhone/iPad (Safari):</b> deelknop → <i>Zet op beginscherm</i>.<br><b>Computer (Chrome/Edge):</b> installatie-icoon rechts in de adresbalk.</p></section>`;}
function settings(){return `<span class="eyebrow">EEN FIJNE BASIS</span><h1>Gezin & instellingen.</h1>${curriculum()}<div class="grid" style="margin-top:20px">${parent?childrenCard():''}${aiCard()}${accountCard()}${parent&&!ephemeral?backupCard():''}${installCard()}</div>`;}
// Beheer (only for the administrator): personal invitations and the trial families. Shows counts, never learning content.
const loadAdmin=async()=>{adminData=await call('GET','/api/admin');};
const day=t=>t?new Date(t).toLocaleDateString('nl-NL',{day:'numeric',month:'short',year:'numeric'}):'—';
const inviteLink=code=>`${location.origin}/?uitnodiging=${encodeURIComponent(code)}`;
const inviteMessage=code=>`Hoi! Je bent uitgenodigd voor de proef van Leerstap: oefenen voor toetsen met je eigen leerstof. Maak jullie gezinsaccount via ${inviteLink(code)}\nJe persoonlijke uitnodigingscode is ${code}. Die werkt één keer.`;
const copyButtons=code=>`${btn('Link kopiëren','copy-text','secondary small',`data-text="${esc(inviteLink(code))}"`)}${btn('Bericht kopiëren','copy-text','secondary small',`data-text="${esc(inviteMessage(code))}"`)}`;
function adminView(){
 if(!adminData)return `<div class="card empty">Beheer wordt geladen…</div>`;
 const {families,invites,limit}=adminData,open=invites.filter(i=>!i.usedAt),paused=families.filter(f=>f.blocked).length,analyses=families.reduce((s,f)=>s+f.analyses,0);
 const newInvite=`<section class="card"><h2>Gezin uitnodigen</h2><p class="muted" style="margin-top:0">Elke uitnodiging heeft een eigen code die één keer werkt. Stuur de link of het bericht via WhatsApp of mail.</p><div class="stack"><div><label for="invite-note">Voor wie? (alleen zichtbaar voor jou)</label><input id="invite-note" maxlength="80" placeholder="Bijvoorbeeld: Familie Jansen"></div>${btn('Uitnodiging maken','admin-invite')}</div>${lastInvite?`<div class="notice success"><b>Uitnodiging${lastInvite.note?` voor ${esc(lastInvite.note)}`:''}</b><div class="recovery-code" style="margin:12px 0">${esc(lastInvite.code)}</div><div class="row">${copyButtons(lastInvite.code)}</div></div>`:''}</section>`;
 const overview=`<section class="card"><h2>Proef in cijfers</h2><div class="stats" style="grid-template-columns:repeat(2,1fr);margin:0 0 15px"><div class="stat"><div><b>${families.length-paused}</b><small>actieve gezinnen${paused?` · ${paused} gepauzeerd`:''}</small></div></div><div class="stat"><div><b>${open.length}</b><small>open uitnodigingen</small></div></div><div class="stat"><div><b>${families.reduce((s,f)=>s+f.children,0)}</b><small>leerlingen</small></div></div><div class="stat"><div><b>${analyses}</b><small>AI-analyses deze maand</small></div></div></div>${adminData.sharedCode?`<div class="notice">Er staat ook een algemene uitnodigingscode ingesteld (<code>INVITE_CODE</code>). Iedereen die die code kent, kan een account maken. Wil je alleen nog persoonlijke uitnodigingen? Verwijder dan het secret <code>INVITE_CODE</code> in Cloudflare.</div>`:''}${adminData.inviteRequired?'':`<div class="notice error">Iedereen kan nu zonder uitnodiging een account maken.</div>`}</section>`;
 const inviteRows=invites.map(i=>`<tr><td>${esc(i.note||'—')}<br><small>${day(i.created)}</small></td><td><code>${esc(i.code)}</code></td><td>${i.usedAt?`<span class="pill">Gebruikt</span><br><small>${i.email?esc(i.email):'gezin verwijderd'} · ${day(i.usedAt)}</small>`:'<span class="pill orange">Nog niet gebruikt</span>'}</td><td>${i.usedAt?'':`<div class="row">${copyButtons(i.code)}${btn('Intrekken','admin-revoke','ghost small danger',`data-code="${esc(i.code)}"`)}</div>`}</td></tr>`).join('');
 const inviteList=`<section class="card" style="margin-top:20px"><h2>Uitnodigingen</h2>${invites.length?`<div style="overflow-x:auto"><table><thead><tr><th>Voor</th><th>Code</th><th>Status</th><th></th></tr></thead><tbody>${inviteRows}</tbody></table></div>`:'<p class="muted">Nog geen uitnodigingen gemaakt.</p>'}</section>`;
 const family=f=>{const self=f.email===me.login,invite=invites.find(i=>i.code===f.invite);return `<div class="list-item"><div class="row between"><div><b>${esc(f.email||'(geen ouderaccount)')}</b> <small>${esc(f.name)}</small></div><div class="row">${self?'<span class="pill">Jij</span>':''}${f.blocked?'<span class="pill orange">Gepauzeerd</span>':''}${f.aiConsent?'<span class="pill">AI-toestemming</span>':''}</div></div><small>${f.children} leerling(en) · ${f.modules} eigen leermodule(s) · ${f.attempts} oefensessie(s) · AI ${f.analyses} van ${limit} deze maand<br>Aangemeld ${day(f.created)}${invite?` via uitnodiging ${esc(invite.note||invite.code)}`:f.invite?'':' met de algemene code of zonder uitnodiging'} · laatst actief ${day(f.lastSeen)}</small>${adminRecovery?.id===f.id?`<div class="notice success"><b>Nieuwe herstelcode voor ${esc(f.email)}</b><p style="margin:4px 0">Geef deze code persoonlijk door (bijvoorbeeld telefonisch). De ouder kiest daarmee via <i>wachtwoord herstellen</i> een nieuw wachtwoord. De oude code werkt niet meer.</p><div class="recovery-code" style="margin:10px 0">${esc(adminRecovery.code)}</div>${btn('Kopiëren','copy-text','secondary small',`data-text="${esc(adminRecovery.code)}"`)}</div>`:''}${self?'':`<div class="row" style="margin-top:10px">${btn(f.blocked?'Hervatten':'Pauzeren','admin-pause','secondary small',`data-id="${esc(f.id)}" data-paused="${!f.blocked}" data-email="${esc(f.email||'')}"`)}${btn('Nieuwe herstelcode','admin-recovery','secondary small',`data-id="${esc(f.id)}" data-email="${esc(f.email||'')}"`)}</div><details><summary class="danger">Gezin verwijderen</summary><p class="muted">Verwijdert alle logins, leerlingen, leerstof, bronnen en resultaten van dit gezin definitief. Dit kan niet ongedaan worden gemaakt.</p><label for="admin-delete-${esc(f.id)}">Jouw wachtwoord</label><input id="admin-delete-${esc(f.id)}" type="password" autocomplete="current-password">${btn('Definitief verwijderen','admin-delete','ghost small danger',`data-id="${esc(f.id)}" data-email="${esc(f.email||'')}"`)}</details>`}</div>`;};
 return `<span class="eyebrow">ALLEEN VOOR JOU ALS BEHEERDER</span><h1>Beheer.</h1><div class="grid">${newInvite}${overview}</div>${inviteList}<section class="card" style="margin-top:20px"><div class="row between"><h2 style="margin:0">Gezinnen</h2>${btn('Vernieuwen','admin-refresh','ghost small')}</div>${families.map(family).join('')}<p class="muted" style="font-size:12px">Je ziet hier alleen het e-mailadres van de ouder en aantallen, geen leerstof, antwoorden of namen van kinderen. <b>Pauzeren</b> meldt het gezin overal af en blokkeert inloggen; de gegevens blijven bewaard.</p></section>`;
}
async function parentMode(){if(parent)return true;toast('Dit kan alleen een ouder doen. Vraag je ouder om in te loggen.');return false;}
async function showSource(id,page){let d=state.documents.find(d=>d.id===id),p=d&&(await pagesOf(d)).find(p=>p.page===page);if(id==='voorbeeld'){p={text:state.modules.find(m=>m.id==='demo')?.chapters[0].summary||'Voorbeeldles wortels'};}if(!p)throw Error('Bronpagina niet gevonden.');const dialog=document.createElement('dialog');dialog.innerHTML=`<div class="row between"><h2>${esc(d?.name||'Voorbeeldles · eigen uitleg')}</h2>${btn('Sluiten','close-dialog','ghost small')}</div><p class="muted">Pagina / tekstdeel ${page}</p>${d?`<div class="row">${Array.from({length:pageCount(d)},(_,i)=>btn(String(i+1),'source-page','ghost small',`data-id="${id}" data-page="${i+1}"`)).join('')}${btn('Download origineel','download-source','secondary small',`data-id="${id}"`)}</div>`:''}${p.image?`<img class="filepreview" src="${esc(p.image)}" alt="Geüploade bronpagina">`:''}<pre>${esc(p.text)}</pre>`;document.body.append(dialog);dialog.showModal();dialog.addEventListener('close',()=>dialog.remove());}
// Brings a decrypted backup (this version or the device-only 0.1/0.2 vault) into the account. Documents upload one by one.
async function importState(incoming){
 validateState(incoming);toast('Back-up wordt overgezet…');
 const r=await call('POST','/api/import',{profiles:incoming.profiles,modules:incoming.modules,attempts:incoming.attempts});let failed=0;
 for(const {pages,data,...meta} of incoming.documents){try{await call('POST','/api/documents',{meta,pages,data});}catch{failed++;}}
 await loadState();route='home';render();toast(`Overgezet: ${incoming.profiles.length} leerling(en), ${incoming.modules.length} leermodule(s), ${incoming.attempts.length} resultaat/resultaten${r.skipped?`, ${r.skipped} al aanwezig`:''}${failed?`. ${failed} bron(nen) lukten niet`:''}.`);
}
const openBackup=async(envelope,password)=>{try{return (await decrypt(envelope,password)).state;}catch{throw Error('Openen lukt niet. Controleer het bestand en het wachtwoord.');}};
async function recordAnswer(){if(!state.draft||!$('#answer'))return;state.draft.answers[questionIndex]={answer:$('#answer').value,steps:$('#steps').value};await save();}
function selectedQuestions(){const m=state.modules.find(m=>m.id===$('#module-select')?.value)||activeModule();if(!m.approved)throw Error('Geef de module eerst vrij.');return {m,questions:chooseQuestions(m,state.attempts,profile,$('#difficulty')?.value||'adaptief',Number($('#count')?.value||5))};}
async function finish(early=false){await recordAnswer();const d=structuredClone(state.draft);if(early){const indices=d.questions.map((q,i)=>i).filter(i=>d.results?.[i]);if(!indices.length){toast('Beantwoord eerst een vraag, of ga later verder.');return;}d.questions=indices.map(i=>d.questions[i]);d.answers=indices.map(i=>d.answers[i]);d.results=indices.map(i=>d.results[i]);}const results=d.questions.map((q,i)=>d.results?.[i]||grade(q,d.answers[i]?.answer||'',d.answers[i]?.steps||'')),review={};d.questions.forEach((q,i)=>{if(!results[i].pending){const previous=review[q.id]||state.attempts.filter(a=>a.profile===profile&&a.review?.[q.id]).at(-1)?.review[q.id];review[q.id]=nextReview(previous,results[i].points===q.points&&!q.support);if(q.repeat&&results[i].points===q.points&&!q.support)review[q.id]=nextReview(null,true);}});state.attempts.push({...d,id:uid(),created:Date.now(),results,review});state.draft=null;practiceResult=null;await save();route='progress';render();}
async function action(el){const a=el.dataset.action;switch(a){
 case 'demo':ephemeral=true;state=initialState();Object.assign(state.profiles[0],{schoolType:'havo/vwo',year:2,subjects:['Wiskunde']});me={role:'parent',name:'Voorbeeld',login:'voorbeeld',familyName:'Voorbeeldgezin',aiConsent:false};profile=state.profiles[0].id;drafts={};route='home';parent=true;render();break;
 case 'auth-view':authView=el.dataset.view;authScreen();break;
 case 'retry':location.reload();break;
 case 'copy-recovery':await navigator.clipboard.writeText(recoveryShown);toast('Herstelcode gekopieerd. Bewaar hem op een veilige plek, niet alleen op dit apparaat.');break;
 case 'download-recovery':download(new Blob([`Leerstap herstelcode\n\n${recoveryShown}\n\nGebruik deze code bij "Wachtwoord vergeten" op de inlogpagina. Bewaar hem veilig.\n`],{type:'text/plain'}),'leerstap-herstelcode.txt');break;
 case 'recovery-done':if(!$('#recovery-saved').checked)throw Error('Bevestig eerst dat je de herstelcode hebt bewaard.');recoveryShown=null;await loadState();route='home';render();toast(parent?'Welkom! Geef je kind bij Gezin & instellingen een eigen login.':'Welkom terug!');break;
 case 'install':if(installPrompt){installPrompt.prompt();await installPrompt.userChoice.catch(()=>{});installPrompt=null;render();}break;
 case 'nav':await recordAnswer();route=el.dataset.route;if(route==='admin')await loadAdmin();practiceResult=null;questionIndex=0;render();break;
 case 'go-library':route='library';render();break;case 'go-practice':route='practice';render();break;
 case 'lock':await recordAnswer();if(!ephemeral){await saveChain.catch(()=>{});await call('POST','/api/logout',{}).catch(()=>{});}state=null;me=null;parent=false;pageCache={};authView=ephemeral?'signup':'login';ephemeral=false;authScreen();break;
 case 'module':selected=el.dataset.id;route='detail';tab='summary';render();break;
 case 'tab':tab=el.dataset.tab;render();break;
 case 'paste':{const text=$('#pasted').value.trim();if(!text)throw Error('Plak eerst leerstof.');const name=($('#pasted-name').value||'Aantekeningen')+'.txt';await addDocument(await extract(new File([text],name,{type:'text/plain'})));render();toast(ephemeral?'Tekst ingelezen (voorbeeldmodus: niet bewaard).':'Tekst veilig bewaard.');break;}
 case 'analyse':{needAccount();if(!ai)throw Error('De AI-koppeling is nog niet ingesteld door de beheerder. Je bronnen blijven bewaard en de voorbeeldles werkt.');const ids=[...document.querySelectorAll('input[name=document]:checked')].map(x=>x.value),docs=state.documents.filter(d=>ids.includes(d.id)&&!d.deletedAt);if(!docs.length)throw Error('Voeg eerst leerstof toe en selecteer een bron.');if(docs.reduce((s,d)=>s+pageCount(d),0)>30)throw Error('Selecteer maximaal 30 pagina’s per analyse.');const consent=$('#consent')?.checked===true;if(!me.aiConsent&&!consent)throw Error(parent?'Vink eerst de toestemming voor AI-analyse aan.':'Vraag je ouder om AI-analyse aan te zetten bij Gezin & instellingen.');el.disabled=true;el.textContent='Leerstof analyseren… dit duurt tot 2 minuten';try{const r=await call('POST','/api/analyse',{documents:docs.map(d=>d.id),subject:$('#subject').value,level:$('#level').value,meta:archiveMeta(),consent});if(consent)me.aiConsent=true;usage.analyses++;state.modules.push(r.module);revs['module:'+r.module.id]=r.rev;markSynced('module:'+r.module.id);selected=r.module.id;route='detail';tab='summary';render();toast(parent?'Klaar! Controleer de leerstof en geef hem vrij.':'Klaar! Je ouder controleert de leerstof en geeft hem vrij.');}finally{el.disabled=false;el.textContent='Maak samenvatting & vragen →';}break;}
 case 'approve':if(await parentMode()){activeModule().approved=true;activeModule().approvedAt=Date.now();await save();render();toast('Leerstof vrijgegeven voor oefenen.');}break;
 case 'remove-module':if(activeModule().demo)throw Error('De voorbeeldmodule blijft beschikbaar.');if(confirm('Deze module naar de prullenbak verplaatsen? Bronnen en eerdere resultaten blijven bewaard.')){activeModule().deletedAt=Date.now();selected='demo';route='library';await save();render();}break;
 case 'save-module-meta':{const m=activeModule(),title=$('#edit-title').value.trim();if(!title)throw Error('Een titel is verplicht.');Object.assign(m,{title,subject:$('#edit-subject').value.trim()||m.subject,schoolYear:$('#edit-year').value.trim(),period:$('#edit-period').value.trim(),chapter:$('#edit-chapter').value.trim(),method:$('#edit-method').value.trim()});await save();render();toast('Leerstof opnieuw ingedeeld.');break;}
 case 'trash-document':{const d=state.documents.find(d=>d.id===el.dataset.id);d.deletedAt=Date.now();await save();render();toast('Bron verplaatst naar de prullenbak. Bestaande bronverwijzingen blijven werken.');break;}
 case 'restore-item':{const list=el.dataset.kind==='document'?state.documents:state.modules;delete list.find(x=>x.id===el.dataset.id).deletedAt;await save();render();toast('Hersteld in het leerarchief.');break;}
 case 'destroy-item':{if(!await parentMode())return;const kind=el.dataset.kind,id=el.dataset.id;if(kind==='document'){const referenced=state.modules.some(m=>m.questions.some(q=>q.cite.source===id)||m.chapters.some(c=>c.cite.source===id))||state.attempts.some(a=>a.questions.some(q=>q.cite.source===id))||state.draft?.questions.some(q=>q.cite.source===id);if(referenced)throw Error('Deze bron hoort nog bij leerstof of een toetsresultaat. Bewaar hem voor controle, of wis de volledige kluis via Instellingen na een back-up.');}if(!confirm('Definitief verwijderen? Dit kan alleen met een eerdere back-up worden hersteld.'))return;if(kind==='document')state.documents=state.documents.filter(d=>d.id!==id);else state.modules=state.modules.filter(m=>m.id!==id);await save();render();toast('Definitief verwijderd.');break;}
 case 'source':await showSource(el.dataset.id,Number(el.dataset.page));break;
 case 'source-page':el.closest('dialog').close();await showSource(el.dataset.id,Number(el.dataset.page));break;
 case 'close-dialog':el.closest('dialog').close();break;
 case 'download-source':{const d=state.documents.find(x=>x.id===el.dataset.id);if(d.data)download(new Blob([unb64(d.data)],{type:d.type}),d.name);else{const a=document.createElement('a');a.href=`/api/documents/${encodeURIComponent(d.id)}/original`;a.download=d.name;a.click();}break;}
 case 'start':{if(state.draft&&!confirm('Er staat een onafgeronde sessie klaar. Wil je die vervangen?'))return;const {m,questions}=selectedQuestions();if(!questions.length)throw Error('Geen vragen op dit niveau beschikbaar.');selected=m.id;state.draft={profile,module:m.id,title:m.title,mode:el.dataset.mode,questions:structuredClone(questions),answers:[],results:[]};questionIndex=0;practiceResult=null;await save();render();break;}
 case 'symbol':{const input=$('#answer'),p=input.selectionStart;input.setRangeText(el.dataset.symbol,p,input.selectionEnd,'end');input.focus();await recordAnswer();break;}
 case 'check':await recordAnswer();{const d=state.draft,q=d.questions[questionIndex],ans=d.answers[questionIndex];if(d.results[questionIndex])break;practiceResult=grade(q,ans.answer,ans.steps);d.results[questionIndex]=practiceResult;schedulePractice(d,questionIndex,practiceResult);await save();render();}break;
 case 'next':await recordAnswer();questionIndex++;state.draft.position=questionIndex;practiceResult=null;await save();render();break;
 case 'previous':await recordAnswer();questionIndex--;state.draft.position=questionIndex;practiceResult=null;await save();render();break;
 case 'finish':await finish();break;
 case 'finish-early':await finish(true);break;
 case 'pdf':{const {m,questions}=selectedQuestions();if(!questions.length)throw Error('Geen vragen beschikbaar.');const answers=el.dataset.answers==='true';makePDF(m,questions,answers).save('leerstap-'+(answers?'antwoorden':'opgaven')+'.pdf');break;}
 case 'review':{if(!await parentMode())return;const a=state.attempts.find(a=>a.id===el.dataset.id),i=Number(el.dataset.index),points=Number($('#score-'+a.id+'-'+i).value),note=$('#note-'+a.id+'-'+i).value.trim(),q=a.questions[i];if(!Number.isFinite(points)||points<0||points>q.points||points*2%1)throw Error('Gebruik halve of hele punten binnen het maximum.');if(!note)throw Error('Geef een korte toelichting op de beoordeling.');a.results[i]={...a.results[i],points,pending:false,confidence:'ouderbeoordeling',reviewNote:note,reviewedAt:Date.now()};a.review[q.id]=nextReview(a.review[q.id],points===q.points);await save();render();toast('Beoordeling en cijfer bijgewerkt.');break;}
 case 'save-subjects':{const p=activeProfile(),schoolType=$('#school-type').value,year=Number($('#school-year').value),subjects=[...document.querySelectorAll('input[name="chosen-subject"]:checked')].map(e=>e.value),custom=$('#custom-subject').value.trim();if(custom)subjects.push(custom);if(!subjects.length)throw Error('Kies minstens één vak.');const max=schoolType.startsWith('vmbo')?4:schoolType==='havo'?5:6;if(year>max)throw Error('Dit schooltype heeft maximaal '+max+' leerjaren.');p.schoolType=schoolType;p.year=year;p.level=year+' '+schoolType;p.subjects=[...new Set(subjects)];await save();render();toast('Je school en vakken zijn bijgewerkt.');break;}
 case 'add-profile':{if(!await parentMode())return;const name=$('#new-name').value.trim(),schoolType=$('#new-type').value,year=Number($('#new-year').value);if(!name)throw Error('Vul een naam of bijnaam in.');if(ephemeral){profile=uid();state.profiles.push({id:profile,name,schoolType,year,level:year+' '+schoolType,subjects:['Wiskunde']});state.draft=null;}else{await save();profile=(await call('POST','/api/profiles',{name,schoolType,year,subjects:['Wiskunde']})).id;await loadState();}render();toast(`${name} is toegevoegd. Kies hierboven de vakken${ephemeral?'':' en geef eventueel een eigen login'}.`);break;}
 case 'child-login':{needAccount();const id=el.dataset.id,login=$('#child-login-'+id).value.trim().toLowerCase(),password=$('#child-password-'+id).value;await call('POST',`/api/profiles/${id}/login`,{login,password});await loadState();render();toast(`Klaar. Je kind logt in met gebruikersnaam ${login} en het gekozen wachtwoord.`);break;}
 case 'remove-child':{needAccount();const p=state.profiles.find(p=>p.id===el.dataset.id);if(!confirm(`${p.name} en alle antwoorden en voortgang definitief verwijderen?`))return;await save();await call('DELETE','/api/profiles/'+p.id);delete drafts[p.id];if(profile===p.id){profile=null;}await loadState();render();toast(`${p.name} is verwijderd.`);break;}
 case 'consent-on':case 'consent-off':{needAccount();me.aiConsent=(await call('POST','/api/family/consent',{consent:a==='consent-on'})).aiConsent;render();toast(me.aiConsent?'Toestemming voor AI-analyse staat aan.':'Toestemming ingetrokken. Er wordt geen leerstof meer naar de AI-dienst gestuurd.');break;}
 case 'change-password':{needAccount();await call('POST','/api/password',{current:$('#pw-current').value,password:$('#pw-new').value});render();toast('Je wachtwoord is gewijzigd. Andere apparaten zijn afgemeld.');break;}
 case 'backup':{needAccount();const password=$('#backup-password').value;if(password.length<10)throw Error('Kies een back-upwachtwoord van minimaal 10 tekens.');await save();toast('Back-up wordt gemaakt…');const data=await call('GET','/api/export'),salt=crypto.getRandomValues(new Uint8Array(16));download(new Blob([JSON.stringify(await encrypt(data,await derive(password,salt),salt))],{type:'application/json'}),'leerstap-backup-'+new Date().toISOString().slice(0,10)+'.json');$('#backup-password').value='';toast('Versleutelde back-up gedownload. Bewaar het wachtwoord apart van het bestand.');break;}
 case 'import':{needAccount();const file=$('#import-file').files[0];if(!file)throw Error('Kies een back-upbestand.');if(file.size>100*1024*1024)throw Error('Back-up is groter dan 100 MB.');let envelope;try{envelope=JSON.parse(await file.text());}catch{throw Error('Dit is geen Leerstap-back-up.');}await save();await importState(await openBackup(envelope,$('#import-password').value));break;}
 case 'import-old-vault':{needAccount();await save();await importState(await openBackup(oldVault,$('#old-vault-password').value));break;}
 case 'copy-text':await navigator.clipboard.writeText(el.dataset.text);toast('Gekopieerd. Plak het in WhatsApp, mail of een bericht.');break;
 case 'admin-refresh':await loadAdmin();render();break;
 case 'admin-invite':{const note=$('#invite-note').value.trim();lastInvite=(await call('POST','/api/admin/invites',{note})).invite;await loadAdmin();render();toast('Uitnodiging gemaakt. Kopieer de link of het bericht.');break;}
 case 'admin-revoke':{if(!confirm(`Uitnodiging ${el.dataset.code} intrekken? De code werkt daarna niet meer.`))return;await call('DELETE','/api/admin/invites/'+encodeURIComponent(el.dataset.code));if(lastInvite?.code===el.dataset.code)lastInvite=null;await loadAdmin();render();toast('Uitnodiging ingetrokken.');break;}
 case 'admin-pause':{const on=el.dataset.paused==='true';if(on&&!confirm(`${el.dataset.email} pauzeren? Het gezin wordt overal afgemeld en kan niet meer inloggen. De gegevens blijven bewaard.`))return;await call('POST',`/api/admin/families/${el.dataset.id}/pause`,{paused:on});await loadAdmin();render();toast(on?'Gezin gepauzeerd.':'Gezin kan weer inloggen.');break;}
 case 'admin-recovery':{if(!confirm(`Nieuwe herstelcode maken voor ${el.dataset.email}? De oude herstelcode werkt daarna niet meer.`))return;adminRecovery={id:el.dataset.id,code:(await call('POST',`/api/admin/families/${el.dataset.id}/recovery`,{})).recoveryCode};render();break;}
 case 'admin-delete':{const password=$('#admin-delete-'+el.dataset.id).value;if(!password)throw Error('Vul je wachtwoord in om te bevestigen.');if(!confirm(`Gezin ${el.dataset.email} met alle gegevens definitief verwijderen?`))return;await call('POST',`/api/admin/families/${el.dataset.id}/delete`,{password});await loadAdmin();render();toast('Gezin verwijderd.');break;}
 case 'delete':{needAccount();if($('#delete-confirm').value!=='VERWIJDER')throw Error('Typ VERWIJDER om te bevestigen.');await call('POST','/api/family/delete',{password:$('#delete-password').value});state=null;me=null;parent=false;authView='signup';authScreen();toast('Jullie gezinsaccount en alle gegevens zijn verwijderd.');break;}
}}
document.addEventListener('submit',e=>{const form=e.target.id;if(!['login-form','signup-form','recover-form'].includes(form))return;e.preventDefault();const b=e.submitter;if(b)b.disabled=true;authSubmit(form).catch(err=>{const box=$('#auth-error');if(box)box.textContent=err.message;else toast(err.message);}).finally(()=>{if(b)b.disabled=false;});});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el)action(el).catch(e=>toast(e.message||'Dit lukte niet. Je gegevens zijn behouden.'));});
document.addEventListener('change',async e=>{try{if(e.target.id==='profile'){await recordAnswer();drafts[profile]=state.draft;profile=e.target.value;state.draft=drafts[profile]||null;questionIndex=0;practiceResult=null;render();}if(e.target.id==='module-select')selected=e.target.value;if(e.target.id==='archive-subject'){archiveSubject=e.target.value;render();}if(e.target.id==='archive-year'){archiveYear=e.target.value;render();}if(e.target.id==='archive-period'){archivePeriod=e.target.value;render();}if(e.target.id==='files'){e.target.disabled=true;toast('Bestanden worden lokaal ingelezen…');let failures=[];for(const f of e.target.files){try{await addDocument(await extract(f));}catch(err){failures.push(f.name+': '+err.message);}}render();toast(failures.length?failures.join(' · '):ephemeral?'Bronnen ingelezen (voorbeeldmodus: niet bewaard).':'Bronnen veilig opgeslagen. Klaar voor analyse.');}}catch(err){toast(err.message);}});
// Typing saves after a short pause instead of on every key.
let typingTimer;document.addEventListener('input',e=>{if(['answer','steps'].includes(e.target.id)){clearTimeout(typingTimer);typingTimer=setTimeout(()=>recordAnswer().catch(()=>{}),800);}});
window.addEventListener('beforeunload',e=>{if(state&&!ephemeral&&saveStatus!=='ok'){e.preventDefault();e.returnValue='';}});
window.addEventListener('online',()=>{if(saveStatus==='error')save().catch(()=>{});});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;if(state)render();});
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
async function start(){
 // An invitation link (?uitnodiging=CODE) opens the signup form with the code filled in.
 const invited=new URLSearchParams(location.search).get('uitnodiging');if(invited){inviteFromLink=invited.trim().toUpperCase().slice(0,40);authView='signup';history.replaceState(null,'',location.pathname);}
 try{const s=await call('GET','/api/status');ai=s.configured;inviteRequired=s.inviteRequired;}catch{}
 storage('get').then(v=>{oldVault=v?.format==='leerstap-v1'?v:null;}).catch(()=>{});
 try{if((await call('GET','/api/session')).user){await loadState();render();return;}}
 catch(e){if(e.status===0){root.innerHTML=`<div class="lockscreen">${intro}<section class="lock-form"><h2>Geen verbinding</h2><p class="muted">Leerstap kan de server niet bereiken. Controleer je internetverbinding.</p>${btn('Opnieuw proberen','retry')}<div class="auth-alt">${btn('Bekijk de voorbeeldles','demo','ghost')}</div></section></div>`;return;}}
 authScreen();
}
start();
